package hexadecimal

import (
	"errors"
	"fmt"
	"math"
)

// ParseHex converts a hexadecimal string to a decimal int64.
// It returns an error containing "syntax" if the input is not a
// valid hexadecimal string, or an error containing "range" if the
// value does not fit in an int64.
func ParseHex(in string) (int64, error) {
	if len(in) == 0 {
		return 0, errors.New("syntax error: empty input")
	}
	var val int64
	for _, c := range in {
		var digit int64
		switch {
		case c >= '0' && c <= '9':
			digit = int64(c - '0')
		case c >= 'a' && c <= 'f':
			digit = int64(c-'a') + 10
		case c >= 'A' && c <= 'F':
			digit = int64(c-'A') + 10
		default:
			return 0, fmt.Errorf("syntax error: invalid character %q", c)
		}
		// overflow check
		if val > (math.MaxInt64-digit)/16 {
			return 0, errors.New("range error: value out of range")
		}
		val = val*16 + digit
	}
	return val, nil
}

// HandleErrors runs ParseHex on each input and reports "none",
// "syntax", or "range" for each result.
func HandleErrors(inputs []string) []string {
	results := make([]string, len(inputs))
	for i, in := range inputs {
		_, err := ParseHex(in)
		switch {
		case err == nil:
			results[i] = "none"
		case strings.Contains(strings.ToLower(err.Error()), "syntax"):
			results[i] = "syntax"
		case strings.Contains(strings.ToLower(err.Error()), "range"):
			results[i] = "range"
		default:
			results[i] = "syntax"
		}
	}
	return results
}
